```python
import sys
from bisect import bisect_left

def main():
	data = list(map(int, sys.stdin.buffer.read().split()))
	it = iter(data)
	n = next(it, None)
	if n is None:
		return
	seq = []
	for _ in range(n):
		m = next(it)
		arr = [next(it) for _ in range(m)]
		# 每层内部升序排序
		arr.sort()
		# 按层拼接
		seq.extend(arr)
	# 严格上升子序列长度（牌堆法 + bisect_left）
	tails = []
	for x in seq:
		i = bisect_left(tails, x)
		if i == len(tails):
			tails.append(x)
		else:
			tails[i] = x
	print(len(tails))

if __name__ == "__main__":
	main()
```

